export function hanz2pinyin(text) {
    if (!table) {
        table = DATA.split(',');
    }
    let out = '';
    for (const ch of text) {
        const cp = ch.codePointAt(0);
        if (cp >= BEGIN && cp <= END) {
            out += table[cp - BEGIN];
        } else {
            out += ch;
        }
    }
    return out;
}
